// Attach an information-arrival record to incidents involving organized factions. Connected factions know immediately;
// others retain courier-style delay. Message contents remain private to their participants.
if(typeof createWorldIncident==='function'){
 const __crystalCreateWorldIncident=createWorldIncident;
 createWorldIncident=function(kind,opts={}){const inc=__crystalCreateWorldIncident.apply(this,arguments);try{if(!inc)return inc;const factions=new Set();for(const f of opts?.political?.factions||[])if(f)factions.add(f);for(const a of opts?.actors||[]){const m=String(a?.ref||'').match(/^faction:(.+)$/);if(m)factions.add(m[1])}if(opts?.political?.faction)factions.add(opts.political.faction);if(factions.size){inc.communicationNotice=inc.communicationNotice||{};for(const faction of factions){const delay=crystalFactionInformationDelay(faction,opts.location);inc.communicationNotice[faction]={noticeDay:state.world.day+delay,delay,source:delay===0?'Crystal Ward portable link':'courier / local reporting'};if(delay===0){const N=crystalNetworkEffectsState();N.incidentNotices.push({day:state.world.day,incidentId:inc.id,faction,kind,location:opts.location||null});N.incidentNotices=N.incidentNotices.slice(-60);crystalNetworkRecord('incident_notice',`${faction} receives immediate notice of a relevant ${String(kind||'world incident').replaceAll('_',' ')} through its portable crystal.`,{faction,incidentId:inc.id})}}}return inc}catch(e){console.error('[Crystal Network Incident Notice]',e);return inc}}
}

// Connected authorities can issue a new regional security response on the following daily cycle even if they
// responded the previous day. This changes information/decision latency only; spawned forces still travel normally.
if(typeof factionSecurityResponseDailyTick==='function'){
 factionSecurityResponseDailyTick=function(){
  if(!isOpenWorld())return;const S=factionSecurityResponseState();if(S.lastTickDay>=state.world.day)return;S.lastTickDay=state.world.day;
  for(const region of state.world.unlockedRegions||['shantium']){
   const threats=state.world.parties.filter(p=>worldPartyDisplayRegion(p)===region&&['bandits','raiders'].includes(p.kind)&&!existingSecurityResponseFor(p.id)).sort((a,b)=>factionSecurityThreatScore(b)-factionSecurityThreatScore(a));
   const threat=threats[0];if(!threat||factionSecurityThreatScore(threat)<3.5)continue;
   const spec=securityFactionForThreat(threat),linked=!!spec?.faction&&crystalFactionHasLiveLink(spec.faction),last=S.lastResponseDay[region]||0,cooldown=linked?1:2;
   if(state.world.day-last<cooldown)continue;
   const response=spawnFactionSecurityResponse(threat);if(response){S.lastResponseDay[region]=state.world.day;if(linked){const N=crystalNetworkEffectsState();N.securityFastResponses++;crystalNetworkRecord('security_response',`${spec.faction} uses its portable link to receive the threat report and issue response orders without an additional courier delay.`,{faction:spec.faction,threatId:threat.id,responseId:response.id})}}
  }
 }
}

