function crystalClientHasPrivateNetwork(b){return !!b&&b.topology==='private_network'&&crystalBookingCrystalIds(b).length>=2&&['active','late'].includes(b.status)}
// A single faction crystal is a Hall link only. It can verify Guardian Hall matters, but no longer grants faction-wide intelligence.
