crystalFactionInformationDelay=function(faction,locId){if(crystalFactionHasPrivateNetwork(faction))return 0;const region=locId&&typeof locationRegion==='function'?locationRegion(locId):null,cap=region==='bluestone'?'zion':region==='redstone'?'sengia':region==='spawn'?'spawn_civic':'shantium';try{return Math.max(1,Math.min(4,Math.ceil((worldTravelDays(cap,locId)||2)*.6)))}catch(e){return 2}};
