// Multi-crystal demand is accepted only when the full requested topology can be supplied after the Guardian's reserve.
crystalProcessDemand=function(){const X=crystalTopologyState(),reserve=Math.max(0,Math.min(2,Number(X.policy?.reserve)||0));let available=crystalAvailableUnits();const waiting=X.demandQueue.filter(d=>d.status==='waiting'&&d.expiresDay>=state.world.day).map(crystalNormalizeDemandTopology).sort((a,b)=>crystalDemandScore(b)-crystalDemandScore(a));let accepted=0;for(const d of waiting){if(available.length-reserve<d.units)continue;const units=available.splice(0,d.units),travel=crystalClientTravelDays({name:d.client,faction:d.faction}),fee=X.dailyRate*d.days*d.units,id='crystal_rental_'+uid(),activeDay=state.world.day+travel,dueDay=activeDay+d.days;for(const c of units){c.status=travel?'in_transit':'rented';c.client=d.client;c.bookingId=id;c.readyDay=travel?activeDay:null}const b={id,type:'rental',term:d.term,crystalId:units[0].id,crystalName:units[0].name,crystalIds:units.map(c=>c.id),crystalNames:units.map(c=>c.name),client:d.client,clientKind:d.clientKind,faction:d.faction,startDay:state.world.day,activeDay,dueDay,status:travel?'in_transit':'active',days:d.days,units:d.units,topology:d.topology,deployments:d.deployments.slice(),fee,deposit:X.deposit*d.units,depositHeld:X.deposit*d.units,privacy:X.privacy,managedBy:'Economic Adviser & Steward',renewalEligible:true,relayAccess:'inherit'};X.bookings.push(b);crystalPruneBookingHistory(X);d.status='accepted';d.bookingId=id;homeFinanceCredit(fee,'Crystal Ward rental',`${d.client} ${CRYSTAL_CONTRACT_TERMS[d.term].name.toLowerCase()} — ${d.units} portable crystal${d.units===1?'':'s'}.`);X.lifetimeRevenue+=fee;X.autoRentals++;const rel=crystalClientRelation(d.client);if(rel.priorityPremium)rel.priorityPremium=false;crystalCommercialLedger('contract',fee,`${d.client} contracted ${d.units} crystal${d.units===1?'':'s'} as a ${crystalTopologyLabel(b)}${travel?`; ${travel} day${travel===1?'':'s'} in transit`:''}.`);accepted++}for(const d of X.demandQueue)if(d.status==='waiting'&&d.expiresDay<state.world.day){d.status='unmet';X.unmetDemand++}return accepted};
// Keep every crystal assigned to a multi-crystal contract synchronized with the primary booking lifecycle.
const __topologyDaily=crystalCommercialDailyTick;crystalCommercialDailyTick=function(){const perf=(name,fn)=>typeof sosPerfRun==='function'?sosPerfRun(name,fn):fn(),r=__topologyDaily.apply(this,arguments),X=crystalTopologyState();return perf('Crystal Ward — Topology Sync',()=>{const crystalById=new Map(X.crystals.map(c=>[c.id,c]));for(const b of X.bookings){const ids=crystalBookingCrystalIds(b);if(b.type!=='rental'||ids.length<=1)continue;const cs=ids.map(id=>crystalById.get(id)).filter(Boolean);if(b.status==='in_transit'&&state.world.day>=b.activeDay)b.status='active';if(['active','late','in_transit'].includes(b.status)){for(const c of cs){c.status=b.status==='in_transit'?'in_transit':'rented';c.client=b.client;c.bookingId=b.id;c.readyDay=b.status==='in_transit'?b.activeDay:null}}else if(b.status==='returned'||b.status==='terminated'){for(const c of cs){if(c.status!=='lost'&&c.status!=='repair'){c.status='available';c.client=null;c.bookingId=null;c.readyDay=null}}}else if(b.status==='lost'){for(const c of cs){if(c.id!==b.crystalId&&c.status!=='lost'){c.status='available';c.client=null;c.bookingId=null;c.readyDay=null}}}}return r})};
const __topologyTerminate=terminateCrystalContract;terminateCrystalContract=function(id){const b=crystalCommercialState().bookings.find(x=>x.id===id),extra=b?crystalBookingCrystals(b).filter(c=>c.id!==b.crystalId):[];const r=__topologyTerminate.apply(this,arguments);for(const c of extra){if(c.status!=='lost'){c.status='available';c.client=null;c.bookingId=null;c.readyDay=null}}save();return r};
