// v1.6.66.22.15 — Crystal Ward booking integrity & mature-save reconciliation
// Live rental contracts are authoritative custody records and must never be discarded by history caps.
function crystalPruneBookingHistory(X=crystalCommercialState(),historicalLimit=160){
 if(!X||!Array.isArray(X.bookings))return [];
 const live=[],history=[];
 for(const b of X.bookings){
  if(b?.type==='rental'&&['in_transit','active','late'].includes(b.status))live.push(b);else history.push(b);
 }
 X.bookings=history.slice(-historicalLimit).concat(live);
 return X.bookings;
}
function crystalCommittedUnitCount(){
 const ids=new Set();
 for(const b of crystalCommercialState().bookings||[])if(b?.type==='rental'&&['in_transit','active','late'].includes(b.status))for(const id of crystalBookingCrystalIds(b))if(id)ids.add(id);
 return ids.size;
}
function crystalActiveContractCount(){return (crystalCommercialState().bookings||[]).filter(b=>b?.type==='rental'&&['in_transit','active','late'].includes(b.status)).length}
function crystalReconcileCommercialCustody(force=false){
 const X=crystalCommercialState();if(!X?.enabled||!Array.isArray(X.crystals)||!Array.isArray(X.bookings))return {changed:false};
 // Once per loaded save-day is enough; the allocator maintains uniqueness after repair.
 if(!force&&X.custodyIntegrity?.version===1&&X.custodyIntegrity.day===state.world.day)return {changed:false};
 const live=X.bookings.filter(b=>b?.type==='rental'&&['in_transit','active','late'].includes(b.status)).sort((a,b)=>(Number(a.startDay)||0)-(Number(b.startDay)||0));
 const byId=new Map(X.crystals.map(c=>[c.id,c])),claimed=new Set(),assignments=new Map(),usable=X.crystals.filter(c=>!['lost','commissioning','repair'].includes(c.status));
 let duplicates=0,reassigned=0,orphans=0;
 for(const b of live){
  const requested=Math.max(1,Number(b.units)||crystalBookingCrystalIds(b).length||1),chosen=[];
  for(const id of crystalBookingCrystalIds(b)){
   const c=byId.get(id);if(!c||claimed.has(id)||['lost','commissioning','repair'].includes(c.status)){if(c&&claimed.has(id))duplicates++;continue}
   chosen.push(id);claimed.add(id);if(chosen.length>=requested)break;
  }
  assignments.set(b.id,{b,requested,chosen});
 }
 // Fill duplicate/missing positions from genuinely usable crystals not already owned by another live contract.
 const free=usable.filter(c=>!claimed.has(c.id));
 for(const rec of assignments.values())while(rec.chosen.length<rec.requested&&free.length){const c=free.shift();rec.chosen.push(c.id);claimed.add(c.id);reassigned++}
 for(const rec of assignments.values()){
  const {b,chosen}=rec;if(!chosen.length)continue;
  b.crystalIds=chosen.slice();b.crystalId=chosen[0];b.units=chosen.length;b.crystalNames=chosen.map(id=>byId.get(id)?.name||'Commercial Crystal');b.crystalName=b.crystalNames[0];
 }
 // Rebuild physical custody from the repaired live-contract map. Unclaimed stale rented/in-transit units return to inventory.
 const owner=new Map();for(const rec of assignments.values())for(const id of rec.chosen)owner.set(id,rec.b);
 for(const c of X.crystals){
  const b=owner.get(c.id);
  if(b){c.status=b.status==='in_transit'?'in_transit':'rented';c.client=b.client;c.bookingId=b.id;c.readyDay=b.status==='in_transit'?b.activeDay:null;continue}
  if(['rented','in_transit'].includes(c.status)){orphans++;c.status='available';c.client=null;c.bookingId=null;c.readyDay=null}
 }
 crystalPruneBookingHistory(X);
 X.custodyIntegrity={version:1,day:state.world.day,repairedDay:state.world.day,duplicates,reassigned,orphans,liveContracts:live.length,committedUnits:claimed.size};
 if(duplicates||reassigned||orphans){crystalCommercialLedger('custody_reconciliation',0,`Crystal Ward custody register reconciled: ${claimed.size} portable crystals assigned across ${live.length} active contracts; ${orphans} stale custody entr${orphans===1?'y':'ies'} cleared.`);homeStaffReport(`The Steward completed a Crystal Ward custody audit. ${claimed.size} portable crystals are now matched to ${live.length} active commercial contracts.`,'info')}
 return {changed:!!(duplicates||reassigned||orphans),duplicates,reassigned,orphans,liveContracts:live.length,committedUnits:claimed.size};
}
